function isInsideCodeFence(lines, lineIndex) {
  let currentFence = null
  let nestStack = []

  for (let i = 0; i < lineIndex; i++) {
    const line = lines[i]

    // An envelope hides its whole body: skip it in a single step through the
    // shared parser, so nested envelopes and fenced examples of the envelope
    // resolve exactly as they do in parseBlocks. Whatever falls inside the
    // skipped range (headings included) is verbatim body content.
    if (!currentFence && getFileChangeOpenTag(line)) {
      const { endIndex } = parseFileChangeBlock(lines, i)
      if (endIndex >= lineIndex) return true
      i = endIndex
      continue
    }

    const fence = getFence(line)
    if (!fence) continue

    if (!currentFence) {
      currentFence = fence
      nestStack = [fence]
      continue
    }

    const lastNested = nestStack[nestStack.length - 1]
    if (lastNested && isClosingFence(lines[i], lastNested)) {
      nestStack.pop()
      continue
    }

    if (!nestStack.length && isClosingFence(lines[i], currentFence)) {
      if (isNestedAnonymousFence(lines, i, 'unknown', currentFence)) {
        nestStack.push(fence)
        continue
      }
      currentFence = null
      nestStack = []
    }
