<script>
import parser from '@/utils/markdownParser'

export default {
  name: 'DocumentSummary',
  props: {
    content: { type: String, default: '' },
    minHeadings: { type: Number, default: 3 },
    documentId: { type: String, default: '' },
    scrollContainer: { type: Object, default: null }
  },
  data() {
    return {
      // Collapse the table of contents by default on mobile to save reading space
      open: !(this.$ui?.isMobile)
    }
  },
  computed: {
    headings() {
      const lines = (this.content || '').split('\n')
      const result = []
      // Counter of the block currently being skipped, shared with parseBlocks:
      // only a closing fence of the block's own delimiter ends it, so a plain
      // compare against '```' (which broke on trailing spaces, CRLF '\r',
      // longer fences and ~~~ closers) is no longer needed.
      let fenceTracker = null

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i]

        // <file_change> envelope: the opening tag carries the file path, the
        // body is verbatim (fences inside it are content) and never
        // contributes TOC entries
        if (!fenceTracker && parser.getFileChangeOpenTag(line)) {
          const { block, endIndex } = parser.parseFileChangeBlock(lines, i)
          if (block.filePath) {
            result.push({
              level: 2,
              text: block.filePath,
              anchor: this.codeAnchor(block.filePath),
              type: 'code',
              lang: block.type,
              fileName: block.filePath.split('/').pop()
            })
          }
          i = endIndex
          continue
        }

        const fence = parser.getFence(line)

        // Inside a code block: skip content, only the matching closing fence
        // ends it (nested fences are counted by the tracker)
        if (fenceTracker) {
          if (fence && parser.trackFence(fenceTracker, fence) === 'close') {
            fenceTracker = null
          }
          continue
        }

        if (fence) {
          // Code block with a file path — this is a TOC entry
          const openMatch = line.match(/^ {0,3}```(\w+)\s+(.+)$/)
          if (openMatch) {
            const [, lang, filePath] = openMatch
            result.push({
              level: 2,
              text: filePath,
              anchor: this.codeAnchor(filePath),
              type: 'code',
              lang,
              fileName: filePath.split('/').pop()
            })
          }
          // Only a fence with an info string opens a block (parseBlocks rule)
          if (fence.info) fenceTracker = parser.createFenceTracker(fence)
          continue
        }

        // Regular markdown heading
        const m = line.match(/^(#{1,6})\s+(.+)$/)
        if (!m) continue
        const text = m[2].trim()
        const slug = text
          .toLowerCase()
          .replace(/[^\w\s-]/g, '')
          .trim()
          .replace(/\s+/g, '-')
        const anchor = this.documentId ? `${this.documentId}-${slug}` : slug
        result.push({ level: m[1].length, text, anchor, type: 'heading' })
      }

      return result
    }
  },
  methods: {
    // Must match the anchor generated by MarkdownViewer's fence renderer
    codeAnchor(filePath) {
      const slug = filePath
        .toLowerCase()
        .replace(/[^\w\s\-./]/g, '')
        .trim()
        .replace(/[\s/]+/g, '-')
      return this.documentId ? `${this.documentId}-${slug}` : slug
    },
    levelIcon(level, type) {
      if (type === 'code') return '📄'
      return ['#', '##', '###', '####', '#####', '######'][level - 1] || '#'
    },
    findScrollableParent(el) {
      if (!el || el === document.body) return null
      const { overflowY } = window.getComputedStyle(el)
      const isScrollable = (overflowY === 'auto' || overflowY === 'scroll') && el.scrollHeight > el.clientHeight
      return isScrollable ? el : this.findScrollableParent(el.parentElement)
    },
    scrollTo(anchor) {
      const target = document.getElementById(anchor)
      if (!target) return

      const container = this.scrollContainer
        || this.findScrollableParent(target)
        || window

      if (container === window) {
        target.scrollIntoView({ behavior: 'smooth', block: 'start' })
        return
      }

      const containerRect = container.getBoundingClientRect()
      const targetRect = target.getBoundingClientRect()
      const offset = targetRect.top - containerRect.top + container.scrollTop - 8
      container.scrollTo({ top: offset, behavior: 'smooth' })
    }
  }
}
</script>
