  assert.equal(blocks.length, 2)
  assert.equal(blocks[0].filePath, 'src/a.js')
  assert.equal(blocks[0].content, 'const a = 1')
  assert.equal(blocks[1].filePath, 'src/b.js')
  assert.equal(blocks[1].content, 'const b = 2')
